\cite[Theorems 5.3 and 5.5]{Strichartz-Asymptotics} \label{Strichartz-theorem}
Let $E \subseteq [0,1]^d$ be a Borel set supporting a positive, finite measure $\vartheta$ that is locally uniformly $s$-dimensional of the form 
\begin{equation} \vartheta = \mathbb H^{s} \bigl|_E + \nu, \label{Strichartz-measure} \end{equation}  where $\mathbb H^{s}|_E$ denotes the $s$-dimensional Hausdorff measure $\mathbb H^s$ restricted to $E$, and  the measure $\nu$ is null with respect to $\mathbb H^{s}$, i.e. $\mathbb H^s(\cdot) < \infty$ implies $\nu(\cdot) = 0$. \footnote{This is slightly different from the Radon-Nikodym theorem; see \cite[Theorem 3.1]{Strichartz-Asymptotics}}
\begin{enumerate}[(a)]
\item Then there exists a constant $C > 0$ such that
\begin{equation} \label{Strichartz-upper} \limsup_{T \rightarrow \infty} T^{s-d} \mathbb F_{\vartheta}(T) \leq C \mathbb H^s(E). \end{equation} 
\vskip0.1in 
\item  If $E$ is also quasi-regular, then there exists a constant $C > 0$ such that 
\begin{equation}  \liminf_{T \rightarrow \infty} T^{s-d} \mathbb F_{\vartheta}(T) \geq C^{-1}\mathbb H^s(E). \label{Strichartz-lower}  \end{equation} 
\vskip0.1in
\item Combining \eqref{Strichartz-upper} and \eqref{Strichartz-lower} leads to the following assertion. Suppose that $E$ is a quasi-regular set supporting a locally uniformly $s$-dimensional probability measure $\mu = \vartheta/||\vartheta||$, with $\vartheta$ given by \eqref{Strichartz-measure}. Then there exists a constant $C_0 \geq 1$ depending on $E$ such that  
\begin{equation} 
C_0^{-1} T^{d-s}\leq \mathbb F_{\mu}(T) \leq C_0 T^{d-s}\quad \text{ for all $T \geq 1$.} \label{Strichartz-upper-lower} 
\end{equation} 
\end{enumerate}

\begin{equation} 
C_0^{-1} T^{d-s}\leq \mathbb F_{\mu}(T) \leq C_0 T^{d-s}\quad \text{ for all $T \geq 1$.} \label{Strichartz-upper-lower} 
\end{equation}

\noindent Given two parameters $0 < \tau_1 \leq \tau_2 < 1$, a (not necessarily infinite) sequence $\{t_j : j \geq 1\} \subseteq (0, 1]$ will be called {\em{$(\tau_1, \tau_2)$-lacunary}} if  
\begin{equation} \label{lacunarity-defn} 
\tau_1 \leq \frac{t_{j+1}}{t_j} \leq \tau_2 \quad \text{ for all $j \geq 1$.}
\end{equation}

\begin{equation} \label{lacunarity-defn} 
\tau_1 \leq \frac{t_{j+1}}{t_j} \leq \tau_2 \quad \text{ for all $j \geq 1$.}
\end{equation}

 \label{quasiregular-distance-thm}
Given any $d \geq 2$, $C_0 \geq 1$ and parameters $0 < \tau_1 \leq \tau_2 < 1$, there exist constants $\varepsilon_0 \in (0, 1)$ and $J_0 \in \mathbb N$  depending on these quantities with the following property. 
\vskip0.1in 
\noindent For $s \in (d - \varepsilon_0, d)$, let $E \subseteq [0,1]^d$ be any quasi-regular Borel set, equipped with a locally uniformly $s$-dimensional probability measure $\mu$  for which \eqref{Strichartz-upper-lower} holds with the specified constant $C_0$. Then $\Delta(E)$ intersects every $J_0$-long sequence that is $(\tau_1, \tau_2)$-lacunary.  Specifically, any sequence $\{t_j : 1 \leq j \leq J_0\} \subseteq (0,1]$ with \eqref{lacunarity-defn} must satisfy 
\begin{equation} \inf_{j \geq 1} \# \Bigl[ \Delta(E) \cap \bigl\{t_{1}, \ldots, t_{J_0}\bigr\} \Bigr] \geq 1. \label{J-consecutive} \end{equation}  
In particular, if $\{t_j : j \geq 1\}$ is any infinite sequence that is $(\tau_1, \tau_2)$-lacunary, then every consecutive block $\{k+1, \ldots, k+J_0\}$ of $J_0$ integers contains an index $j$ with $t_j \in \Delta(E)$.

For any Borel set $E \subseteq [0,1]^d$ and $s \in (0, d]$, the standard {\em{$s$-dimensional Hausdorff measure}} $\mathbb H^s(E)$\cite[Chapter 2]{Mattila-Book2} is defined as: 
\begin{equation}  
\mathbb H^s(E) := \lim_{r \rightarrow 0+} \inf \Bigl\{\sum_{i=1}^{\infty} \bigl[\text{diam}(E_i) \bigr]^s : E \subseteq \bigcup_{i=1}^{\infty} E_i, \; \text{diam}(E_i) \leq r \Bigr\}, 
\end{equation}
where the infimum is taken over all countable covers of $E$ consisting of sets $E_i$ with diameter at most $r$.

\begin{equation}  
\mathbb H^s(E) := \lim_{r \rightarrow 0+} \inf \Bigl\{\sum_{i=1}^{\infty} \bigl[\text{diam}(E_i) \bigr]^s : E \subseteq \bigcup_{i=1}^{\infty} E_i, \; \text{diam}(E_i) \leq r \Bigr\}, 
\end{equation}

\begin{align}  
\mathcal H^s(E) &:=  \lim_{r \rightarrow 0+} \inf \Bigl\{\sum_{i=1}^{\infty} \ell(Q_i)^s : E \subseteq \bigcup_{i=1}^{\infty} Q_i, \; Q_i \in \mathcal Q_d, \ell(Q_i) \leq r \Bigr\}, \noindent \\ 
 \mathcal H_{\infty}^{s}(E) &:= \inf \Bigl\{ \sum_{i=1}^{\infty} \ell(Q_i)^s : E \subseteq \bigcup_{i=1}^{\infty} Q_i, \; Q_i \in \mathcal Q_d \Bigr\}. \label{dyadic-H-content-def}
 \end{align}

