Setting $\sigma := d/s > 1$ and $\mathbb Z_{q} := \{0, 1, \ldots,  q - 1\}$, we define $\mathtt F = \mathtt F[q] \subseteq [0,1]^d$ as follows, 
\begin{equation} \label{def-building-block-F} 
\mathtt F = \mathtt F[q; \sigma] := \bigcup \left\{\frac{p}{q} + {q}^{-\sigma}[0,1]^d \; \Bigl| \; p \in \mathbb Z_{q}^d \right\}. 
\end{equation}

\begin{equation} \label{def-building-block-F} 
\mathtt F = \mathtt F[q; \sigma] := \bigcup \left\{\frac{p}{q} + {q}^{-\sigma}[0,1]^d \; \Bigl| \; p \in \mathbb Z_{q}^d \right\}. 
