 \vskip0.1in
 \item 

 Near the origin, $\Delta(\mathtt F)$ is a disjoint union of intervals of length $\sim q^{-\sigma}$. Specifically, 
 \begin{equation} \bigsqcup \bigl\{\mathtt J_r : r \in \mathcal R, \, r \leq \frac{c_0}{2}q^{\sigma-1} \bigr\} \subseteq \Delta(\mathtt F) \cap \bigl[0, c_0q^{\sigma-2} \bigr) \subseteq \bigsqcup \bigl\{\mathtt I_r : r \in \mathcal R, \,  r \leq 2c_0 q^{\sigma-1} \bigr\}. \label{F-E-small-r} \end{equation} \label{small-disjoint-intervals}
 \item For $r \in \mathcal R$ with ${q^{2(\sigma-1)}}/{c_0^2} - 1\leq r < q$, the union of the intervals $\mathtt J_r$ consists of a single interval whose length is bounded from below by an absolute constant. As a result, 
 \begin{equation} \label{large-interval} 
 \Delta(\mathtt F) \supseteq   \Bigl[c_0^{-2}q^{2\sigma -3}, 1 \Bigr].
 \end{equation} 
 \label{large-single-interval}
 \end{enumerate}

\begin{equation} \label{large-interval} 
 \Delta(\mathtt F) \supseteq   \Bigl[c_0^{-2}q^{2\sigma -3}, 1 \Bigr].
 \end{equation}


The proof is of a number-theoretic flavour. The argument is especially simple for $d \geq 4$ and yields slightly stronger statements than those claimed in \eqref{claim0} and \eqref{large-interval}. We address this scenario separately. According to Lagrange's theorem \cite[\S 20.5, p 302, Theorem 369]{Hardy-Wright}, every positive integer $k$ is the sum of four squares, i.e., the sum of square of four non-negative integers. Thus, 
\begin{align*} 
&\text{for $d \geq 4$ and any integer $k$ with $\sqrt{k} \in \bigl(\frac{2}{c_0}q^{\sigma-1}, q \bigr)$,} \\  
&\text{there exist $p, p' \in \mathbb Z_q^d - \mathbb Z_q^d \;$ such that $k = |p|^2$ and $k + 1= |p'|^2$.}
\end{align*}
In fact, $p, p'$ can be chosen to have no more than four non-zero coordinates, each of which must be strictly smaller than $q$ in absolute value. Consequently, $r = \sqrt{k} = |p| \in \mathcal R$, $r' = \sqrt{k+1} = |p'| \in \mathcal R$, and    
\[ r' - r = \sqrt{k+1} - \sqrt{k} = \frac{1}{\sqrt{k+1} + \sqrt{k}} \leq \bigl[ \frac{2}{c_0} q^{\sigma-1} \bigr]^{-1} \leq 2 \gamma_d q^{1 - \sigma}. \]
The last inequality follows from the assumption $c_0 \in (0, \gamma_d/100)$. This proves \eqref{claim0} for $r$ in the bigger range $|r| > 2q^{\sigma -1}/c_0$, which in turn leads to $\Delta(\mathtt F) \supseteq [2q^{\sigma-2}/c_0, 1]$, a bigger interval than the one claimed in \eqref{large-interval}.  
\vskip0.1in
\noindent The above argument involving Lagrange's theorem does not apply for $d = 2,3$. However, there is a wealth of number-theoretic literature addressing the asymptotic behaviour of integers that can be represented as a sum of two squares \cite{{Landau-1908}, {Berndt-Rankin-1995}, {Hardy-Ramanujan}, {Moree-Cazaran}}. In particular, the following result of Bambah and Chowla \cite{Bambah-Chowla-1947}, reproduced in \cite[p.137]{Halberstam-1983}, offers a viable substitute: For all $m \geq 1154$, the interval $(m, m+3m^{1/4})$ contains an integer that is expressible as the sum of two squares.  Thus, for $q$ sufficiently large, $r \in \mathcal R$, and  
\begin{align*}
&\text{$r = \sqrt{k} \in \Bigl[\frac{q^{2(\sigma-1)}}{c_0^2}-1, q \Bigr]$, one can find an integer $u\in \bigl[1, 3k^{\frac{1}{4}} \bigr]$ such that } \\ 
&\text{$k' = k+u$ can be expressed as $k' = |p'|^2 = r'^2$ for some $p' \in \mathbb Z_q^{d}$.} 
\end{align*} 
In  fact, \cite{Bambah-Chowla-1947} ensures that $p'$ can be chosen to have at most two nonzero coordinates, each smaller than $q$. Substituting this into $||p| - |p'|| = |r' - r|$ leads to the expression
\[ |r' - r| = \sqrt{k+u} - \sqrt{k} = \frac{u}{\sqrt{k+u} + \sqrt{k}}
\leq \frac{3k^{\frac{1}{4}}}{\sqrt{k}} \leq 3 k^{-\frac{1}{4}} \leq 6c_0 q^{1 - \sigma} \leq 2\gamma_d q^{1 - \sigma}. \] 
This completes the proof of \eqref{claim0} in all dimensions $d \geq 2$.

