\[ \mathtt F[\mathtt q_n] \subseteq A_{R_n}(x_n)  \subseteq [0,1]^d \quad \text{ and hence } \quad  \mathcal H_{\infty}^s \bigl(A_{R_n}(x_n) \bigr) =1 \text{ for every $n \geq 1$},  \]
