\end{equation}  
Conversely, if the integral in \eqref{mass-Lambda-mu-nu} s strictly positive, then $\Lambda_{\mu, \nu}(t)$ is a non-trivial measure, and hence its support $X_{\mu}(t)$ is non-empty; in other words, $t \in \Delta(E, F)$. 
\end{enumerate}

